export function projectClassicalParticleHonorificAvailability(control, available, honorificized) {
  const wrapper = control?.closest?.('.classical-rule-control');
  if (!wrapper) return;
  wrapper.hidden = !available;
  wrapper.setAttribute('aria-hidden', String(!available));
  wrapper.setAttribute('aria-disabled', String(!available));
  wrapper.dataset.classicalControlAvailability = available ? 'enabled' : 'hidden';
  wrapper.dataset.classicalAuthorityUserInput = available ? 'required' : 'not-present';
  wrapper.dataset.classicalRuleLogicCurrentVisibility = available ? 'visible' : 'hidden';
  control.disabled = !available;
  control.setAttribute('aria-disabled', String(!available));
  control.checked = available && honorificized === true;
}

export function getClassicalDerivationOptionLabel(option = {}, fallbackDerivationType = "") {
  const withoutSourceReference = value => String(value || "")
    .replace(/\s*·\s*Andrews\s+§[0-9.]+/giu, "")
    .replace(/\s*·\s*§[0-9.]+/gu, "")
    .trim();
  const derivationName = String(
    option.derivationType || fallbackDerivationType || "",
  ).trim();
  const rawSubtype = String(
    option.derivationSubtype || option.formationType || option.operationType || "",
  ).trim();
  if (["causative", "applicative"].includes(derivationName) && rawSubtype) {
    const numberedSubtype = rawSubtype === "type-one"
      ? "Type 1"
      : rawSubtype === "type-two"
        ? "Type 2"
        : rawSubtype === "type-three"
          ? "Type 3"
          : rawSubtype.split("-").map((part, index) => (
            index === 0
              ? `${part.charAt(0).toUpperCase()}${part.slice(1)}`
              : part
          )).join(" ");
    const typedOperation = String(
      option.targetConstruction?.operation || option.procedure || "",
    );
    const procedure = option.targetConstruction?.irregular === true
      ? "irregular replacement"
      : typedOperation.includes("nonactive")
      ? "nonactive replacement"
      : typedOperation.includes("replace")
        ? "morphological replacement"
        : /append|add/u.test(typedOperation)
          ? "addition"
          : "grammar-supported formation";
    const sourceHistoryChoice = String(option.sourceHistoryChoice || "").trim();
    return [
      numberedSubtype,
      option.targetStem || option.derivedStem,
      option.shuntlineReflexivePosition === "late"
        ? option.shuntlineReflexiveBoundaryVariant === "ihyana-contracted"
          ? "tē + ne (contracted)" : "tē + ne" : "",
      sourceHistoryChoice ? `Source history: ${sourceHistoryChoice}` : "",
      procedure,
      !sourceHistoryChoice && option.lexicalChoiceRequired === true
        ? "lexical choice"
        : "",
    ].filter(Boolean).join(" · ");
  }
  return withoutSourceReference(
    option.label
    || option.optionLabel
    || [
      option.formationType || option.operationType || option.optionId,
      option.targetStem || option.derivedStem,
    ].filter(Boolean).join(" → "),
  );
}

// Presentation only: callers supply the exact Result from a validated binding.
export function getClassicalBoundVncSourceParts(exactResult = null) {
  const nucleus = exactResult?.vncApplicationFrame?.resultFrame
    || exactResult?.resultFrame || exactResult;
  const analysis = nucleus?.sourceAnalysisFrame;
  const selection = analysis?.sourceMachineryFrame?.sourceSelectionFrame
    || analysis?.formationSourceMachineryFrame?.sourceSelectionFrame
    || nucleus?.formationSourceMachineryFrame?.sourceSelectionFrame
    || nucleus?.sourceMachineryFrame?.sourceSelectionFrame
    || nucleus?.selectedMachineryFrame?.sourceSelectionFrame;
  return selection?.selectedSourceKind === "embed-matrix"
    && selection.selectedEmbedStem && selection.selectedMatrixStem
    ? {sourceEmbedStem: selection.selectedEmbedStem,
        sourceMatrixStem: selection.selectedMatrixStem}
    : null;
}

