          displayTextAuthority: false,
          selectedFormula: "",
          wordSurface: "",
          sentenceFormula: "",
          sentenceSurface: "",
          sentenceFormulaAttachment: "",
          vncSentenceResultFrame: null,
          diagrammaticFrame: null,
          fixedReference: null,
          conditions: [],
          witnessRefs: []
