          group.dataset.classicalVncAuthorityControlGroup = kind;
          const header = targetObject.document.createElement("div");
          header.className = "classical-vnc-authority-control-group__header";
          header.textContent = title;
          const body = createStage(`particle-${kind}`, `${title} controls`);
