      const typedOperation = String(typedConstruction?.operation || "");
      const compactOperation = typedOperation === "replace-morpheme-and-append"
        && typedConstruction?.remove && typedConstruction?.replaceWith && typedConstruction?.add
        ? `replace ${typedConstruction.remove} with ${typedConstruction.replaceWith}; add ${typedConstruction.add}`
        : typedOperation.includes("replace")
