      const sameSurfaceOperation = String(projection.stemRelation || "").startsWith("surface-identical");
      const operationAccount = sameSurfaceOperation
        ? `same spelling; ${sourceValence} → ${resultValence}; ${participantAccount}`
        : participantAccount;
      appendAccountSegment("Source VNC", surfaceModel.source.stem, `${sourceValence} · ${sourceSubjectAccount}`, "source");
      appendAccountArrow();
      appendAccountSegment(derivationType === "causative" ? "Causative" : "Applicative", "", operationAccount, "operation");
      appendAccountArrow();
      appendAccountSegment("Resulting VNC", surfaceModel.result.stem, resultValence, "result");
      detailsBody.appendChild(route);
      appendDetail("Source class", surfaceModel.source.verbClass, "source-class");
