      appendDetail("Participant binding", surfaceModel.operation.participantBinding.replace(/-/gu, " "), "participant-binding");
      appendDetail("Object position", surfaceModel.operation.participantRole.replace(/-/gu, " "), "object-position");
      appendDetail("Stem relation", String(projection.stemRelation || "surface-changing").replace(/-/gu, " "), "stem-relation");
