    function installClassicalParadigmOutsideClickDismissal() {
      const documentObject = targetObject.document;
      if (!documentObject?.addEventListener || classicalParadigmOutsideClickDocuments.has(documentObject)) return;
      documentObject.addEventListener("click", event => {
        documentObject.querySelectorAll?.([
          ".classical-rule-surface__vnc-paradigm-form[open]",
          ".classical-rule-surface__paradigm-map-form[open]"
        ].join(",")).forEach(details => {
          if (!details.contains(event.target)) details.open = false;
        });
      });
      documentObject.defaultView?.addEventListener("resize", () => {
        documentObject.querySelectorAll?.(
          ".classical-rule-surface__paradigm-map-form[open]"
        ).forEach(form => updateClassicalNncParadigmPopupDirection(form));
      });
      classicalParadigmOutsideClickDocuments.add(documentObject);
    }
    function updateClassicalNncParadigmPopupDirection(form = null) {
      if (!form?.open || typeof form.getBoundingClientRect !== "function") return "";
      const detail = form.querySelector?.(".classical-rule-surface__vnc-paradigm-detail");
      const boundary = form.closest?.(".classical-rule-surface__paradigm-map-group");
      if (!detail || !boundary) return "";
      const formRect = form.getBoundingClientRect();
      const detailRect = detail.getBoundingClientRect();
      const boundaryRect = boundary.getBoundingClientRect();
      const forwardLeft = formRect.left;
      const forwardRight = forwardLeft + detailRect.width;
      const backwardRight = formRect.right;
      const backwardLeft = backwardRight - detailRect.width;
      const overflow = (left, right) => (
        Math.max(0, boundaryRect.left - left)
        + Math.max(0, right - boundaryRect.right)
      );
      const direction = overflow(forwardLeft, forwardRight)
        <= overflow(backwardLeft, backwardRight)
        ? "forward"
        : "backward";
      form.dataset.classicalNncPopupDirection = direction;
      return direction;
    }
