        const continuation = token.role === "principal" ? canonical.principalContinuationFrames?.at(-1)
          : ["supplement", "topic-supplement"].includes(token.role) ? canonical.supplementContinuationFrames?.at(-1) : null;
        const context = continuation || targetObject.getClassicalNahuatlSupplementationClauseSourceFrame?.(envelope)
          || envelope || canonical;
