        projected = targetObject.executeClassicalGrammarApplicationRequest({operationId: applicationResult.operationId,
          outputKind: "coordinate-projection", args: ordinaryNnc ? [prepared.canonicalResult] : [prepared.canonicalResult, coordinates]});
