      wholeComposition = wholeComposition || (
        typeof ActiveClassicalClauseRelationResult !== "undefined"
        && ActiveClassicalClauseRelationResult?.canonicalResult === exactResult
      );
      const retainedResult = Boolean(
        ActiveClassicalCapabilityApplicationResult?.authorizationStatus === "authorized"
          && ActiveClassicalCapabilityApplicationResult.canonicalResult === exactResult
        || ActiveClassicalGrammarResultSourceCapture?.canonicalResult === exactResult
        || ActiveClassicalClauseRelationResult?.canonicalResult === exactResult
      );
